<?php $o=$order; $items=query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll(); $shipment=query('SELECT * FROM shipments WHERE order_id=?',[$o['id']])->fetch(); ?>
<section class="section"><p class="eyebrow">THANK YOU FOR CHOOSING WIKI</p><h1>Your order, in motion.</h1><p><?=e($o['number'])?> · <?=e($o['created_at'])?></p><div class="checkout-grid"><div><div class="panel"><h2><?=e(ucwords(str_replace('_',' ',$o['status'])))?></h2><p>Payment: <?=e($o['payment_status'])?></p><?php if($shipment): ?><p><?=e($shipment['carrier'])?> · Tracking number: <strong><?=e($shipment['tracking_number'])?></strong></p><?php endif ?></div><?php foreach($items as $i): ?><div class="order-row"><strong><?=e($i['name'])?></strong><span><?=e($i['variant'])?></span><span>Qty <?=e($i['quantity'])?></span><span><?=money($i['unit_price']*$i['quantity'])?></span></div><?php endforeach ?><h2>Delivery address</h2><p><?=e($o['customer_name'])?><br><?php foreach(json_decode($o['shipping_address'],true) as $value) echo e($value).'<br>'; ?></p><?php if($o['status']==='delivered'): ?><form class="form-panel" method="post" action="/api/action" data-ajax><?=csrf_field()?><input type="hidden" name="action" value="return"><input type="hidden" name="number" value="<?=e($o['number'])?>"><h3>Request a return</h3><label>Tell us what happened<textarea name="reason" required maxlength="2000"></textarea></label><button class="btn secondary">Submit request</button></form><?php endif ?></div><aside class="order-summary"><h2>Order summary</h2><?php $totals=$o; require ROOT.'/views/partials/totals.php'; ?><p>Need a hand? <a class="underlined" href="/contact">Contact us</a>.</p></aside></div></section>
